static void coroutine_fn bdrv_create_co_entry(void *opaque) /* <=== bdrv_create_co_entry */ 
{
    Error *local_err = NULL;
    int ret;

    CreateCo *cco = opaque;
    assert(cco->drv);

    ret = cco->drv->bdrv_create(cco->filename, cco->options, &local_err);
    if (local_err) {
        error_propagate(&cco->err, local_err);
    }
    cco->ret = ret;
}

static int bdrv_check_request(BlockDriverState *bs, int64_t sector_num, /* <=== bdrv_check_request */ 
                              int nb_sectors)
{
    if (nb_sectors > INT_MAX / BDRV_SECTOR_SIZE) {
        return -EIO;
    }

    return bdrv_check_byte_request(bs, sector_num * BDRV_SECTOR_SIZE,
                                   nb_sectors * BDRV_SECTOR_SIZE);
}

static void coroutine_fn bdrv_rw_co_entry(void *opaque) /* <=== bdrv_rw_co_entry */ 
{
    RwCo *rwco = opaque;

    if (!rwco->is_write) {
        rwco->ret = bdrv_co_do_preadv(rwco->bs, rwco->offset,
                                      rwco->qiov->size, rwco->qiov,
                                      rwco->flags);
    } else {
        rwco->ret = bdrv_co_do_pwritev(rwco->bs, rwco->offset,
                                       rwco->qiov->size, rwco->qiov,
                                       rwco->flags);
    }
}

static void coroutine_fn bdrv_get_block_status_co_entry(void *opaque) /* <=== bdrv_get_block_status_co_entry */ 
{
    BdrvCoGetBlockStatusData *data = opaque;
    BlockDriverState *bs = data->bs;

    data->ret = bdrv_co_get_block_status(bs, data->sector_num, data->nb_sectors,
                                         data->pnum);
    data->done = true;
}

int coroutine_fn bdrv_is_allocated(BlockDriverState *bs, int64_t sector_num, /* <=== bdrv_is_allocated */ 
                                   int nb_sectors, int *pnum)
{
    int64_t ret = bdrv_get_block_status(bs, sector_num, nb_sectors, pnum);
    if (ret < 0) {
        return ret;
    }
    return
        (ret & BDRV_BLOCK_DATA) ||
        ((ret & BDRV_BLOCK_ZERO) && !bdrv_has_zero_init(bs));
}

static void coroutine_fn bdrv_flush_co_entry(void *opaque) /* <=== bdrv_flush_co_entry */ 
{
    RwCo *rwco = opaque;

    rwco->ret = bdrv_co_flush(rwco->bs);
}

static void coroutine_fn bdrv_discard_co_entry(void *opaque) /* <=== bdrv_discard_co_entry */ 
{
    DiscardCo *rwco = opaque;

    rwco->ret = bdrv_co_discard(rwco->bs, rwco->sector_num, rwco->nb_sectors);
}

